objs={4:{(3,7),(4,6),(4,8),(5,5),(5,6),(5,8)},2:{(3,13),(4,12),(5,11),(21,21),(21,22)},3:{(11,15),(12,16),(13,16)},5:{(9,25),(10,24),(10,25)},6:{(11,5),(12,5),(12,7)},7:{(19,11),(20,12)},8:{(1,23),(2,22),(3,22)},9:{(22,5),(23,3)}}
S={(0,2),(1,1),(1,3),(2,0),(2,1),(2,3)}
trans=[]
for refl in [False,True]:
 for k in range(4):
  t=set()
  for r,c in S:
   if refl:c=-c
   for _ in range(k):r,c=c,-r
   t.add((r,c))
  mr=min(r for r,c in t);mc=min(c for r,c in t)
  t={(r-mr,c-mc) for r,c in t}
  if t not in trans:trans.append(t)
groups={2:[{(3,13),(4,12),(5,11)},{(21,21),(21,22)}],3:[objs[3]],5:[objs[5]],6:[objs[6]],7:[objs[7]],8:[objs[8]],9:[objs[9]]}
for col, gg in groups.items():
 for pts in gg:
  r0=min(r for r,c in pts);r1=max(r for r,c in pts);c0=min(c for r,c in pts);c1=max(c for r,c in pts)
  br=(r0+r1)/2;bc=(c0+c1)/2
  cand=[]
  for i,t in enumerate(trans):
   for r in range(30):
    for c in range(30):
     fp={(r+dr,c+dc) for dr,dc in t}
     if pts<=fp:
      fr=min(x for x,y in fp);fc=min(y for x,y in fp);lr=max(x for x,y in fp);lc=max(y for x,y in fp)
      score=((fr+lr)/2-br)**2+((fc+lc)/2-bc)**2
      cand.append((score,i,r,c,fp))
  score,i,r,c,fp=min(cand,key=lambda x:(x[0],x[1],x[2],x[3]))
  print(col, sorted(pts), '=>',round(score,3),i,r,c,sorted(fp))

