objs={4:{(3,7),(4,6),(4,8),(5,5),(5,6),(5,8)},2:{(3,13),(4,12),(5,11),(21,21),(21,22)},3:{(11,15),(12,16),(13,16)},5:{(9,25),(10,24),(10,25)},6:{(11,5),(12,5),(12,7)},7:{(19,11),(20,12)},8:{(1,23),(2,22),(3,22)},9:{(22,5),(23,3)}}
S={(0,2),(1,1),(1,3),(2,0),(2,1),(2,3)}
# New hypothesis: overlay color-4 motif once at every object using its natural bounding-box top-left, even if that does not cover every seed.
placements={2:[(3,11),(19,21)],3:[(11,13)],5:[(8,24)],6:[(10,4)],7:[(19,9)],8:[(1,21)],9:[(21,2)]}
G=[[1]*30 for _ in range(30)]
for color,pts in objs.items():
 for r,c in pts:G[r][c]=color
for color,anchors in placements.items():
 for ar,ac in anchors:
  for dr,dc in S:G[ar+dr][ac+dc]=color
assert len(G)==30 and all(len(row)==30 for row in G)
assert all(G[r][c]==color for color,pts in objs.items() for r,c in pts)
print(json.dumps({'action':'submit','grid':G},separators=(',',':')))
